<template><div class="page-wrap"><div class="page-heading"><span class="eyebrow">BROWSE BY CATEGORY</span><h1>游戏分类</h1><p>按喜欢的玩法，开启一段新旅程。</p></div><div class="category-page-grid"><RouterLink v-for="c in categories" :key="c.id" :to="{path:'/games',query:{category:c.id}}" class="category-large" :class="`cat-${c.color}`"><span class="category-icon">{{ c.icon }}</span><h2>{{ c.name }}</h2><p>{{ c.description }}</p><small>{{ count(c.id) }} 款游戏</small><b>浏览游戏 →</b></RouterLink></div></div></template>
<script setup>import {inject,computed} from 'vue';const data=inject('siteData'),categories=computed(()=>[...data.categories].sort((a,b)=>a.sortOrder-b.sortOrder));function count(id){return data.games.filter(g=>g.published&&g.categoryIds?.includes(id)).length}</script>
